mapper.select:
/* BatchJobMapper.selectBatchJobList 검색 조건에 맞는 배치직무 목록을 조회한다. */



        AND J.WRK_MDUL_CD = #{wrkMdulCd}


        AND J.USE_YN = #{useYn}


        AND (J.JOB_ID ILIKE '%' || #{keyword} || '%' OR J.JOB_NM ILIKE '%' || #{keyword} || '%')


        AND L.EXEC_ST_DTTM >= TO_DATE(#{lastExecDt}, 'YYYYMMDD')
        AND L.EXEC_ST_DTTM < TO_DATE(#{lastExecDt}, 'YYYYMMDD') + 1


        AND L.EXEC_STAT_CD = #{lastExecStatCd}


ORDER BY J.WRK_MDUL_CD, J.JOB_ID

